栈和队列都是“只能从特定位置进出”的序列，规则限制越多，用起来反而越不容易出错。

```mermaid
flowchart LR
  accTitle: 栈从同一端进出；队列从队尾进、从队头出
  subgraph S["栈：append 和 pop 都在栈顶"]
    direction LR
    s1["1"] --- s2["2"] --- s3["3（栈顶）"]
  end
  subgraph Q["队列：append 进队尾，popleft 出队头"]
    direction LR
    q1["1（队头）"] --- q2["2"] --- q3["3（队尾）"]
  end
  push(["push 4"]) --> s3
  s3 --> pop(["pop 得到 3"])
  enq(["append 4"]) --> q3
  q1 --> deq(["popleft 得到 1"])
```

## 栈：后进先出（LIFO）

栈像一摞盘子，只能在顶上放、从顶上拿。Python 直接用 `list` 当栈：

```python
stack = []
stack.append(1)    # 入栈，O(1)
stack.append(2)
top = stack[-1]    # 看栈顶，O(1)
stack.pop()        # 出栈，返回 2，O(1)
```

```cpp
void demo() {
    vector<int> stack;
    stack.push_back(1);      // 入栈，O(1)
    stack.push_back(2);
    int top = stack.back();  // 看栈顶，O(1)
    stack.pop_back();        // 出栈，O(1)；C++ 的 pop 不返回值
}
```

```java
import java.util.*;

static void demo() {
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(1);           // 入栈，O(1)
    stack.push(2);
    int top = stack.peek();  // 看栈顶，O(1)
    stack.pop();             // 出栈，返回 2，O(1)
}
```

```go
import "fmt"

func demo() {
	stack := []int{}
	stack = append(stack, 1)     // 入栈，O(1)
	stack = append(stack, 2)
	top := stack[len(stack)-1]   // 看栈顶，O(1)
	stack = stack[:len(stack)-1] // 出栈，O(1)
	fmt.Println(top, stack)      // 2 [1]
}
```

**什么时候想到栈？** 当“最近出现的东西最先被处理”时：括号匹配、撤销操作、函数调用栈、深度优先搜索，以及后面会学的单调栈。

### 例子：有效的括号

遇到左括号就入栈；遇到右括号，它必须和**最近一个还没配对的左括号**匹配，也就是栈顶：

```python
def is_valid(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            stack.append(ch)
    return not stack   # 最后不能剩下没配对的左括号
```

```cpp
bool isValid(const string& s) {
    unordered_map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};
    vector<char> stack;
    for (char ch : s) {
        if (pairs.count(ch)) {
            if (stack.empty() || stack.back() != pairs[ch]) return false;
            stack.pop_back();
        } else {
            stack.push_back(ch);
        }
    }
    return stack.empty();  // 最后不能剩下没配对的左括号
}
```

```java
import java.util.*;

static boolean isValid(String s) {
    Map<Character, Character> pairs = Map.of(')', '(', ']', '[', '}', '{');
    Deque<Character> stack = new ArrayDeque<>();
    for (char ch : s.toCharArray()) {
        if (pairs.containsKey(ch)) {
            char open = pairs.get(ch);
            if (stack.isEmpty() || stack.pop() != open) return false;
        } else {
            stack.push(ch);
        }
    }
    return stack.isEmpty();  // 最后不能剩下没配对的左括号
}
```

```go
func isValid(s string) bool {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	stack := []rune{}
	for _, ch := range s {
		if open, ok := pairs[ch]; ok {
			if len(stack) == 0 || stack[len(stack)-1] != open {
				return false
			}
			stack = stack[:len(stack)-1]
		} else {
			stack = append(stack, ch)
		}
	}
	return len(stack) == 0 // 最后不能剩下没配对的左括号
}
```

每个字符最多入栈、出栈各一次，时间 O(n)，空间 O(n)。

## 队列：先进先出（FIFO）

队列像排队，从队尾进、从队头出。**不要用 `list.pop(0)` 当出队**：它要把后面的元素全部前移，是 O(n)。用 `collections.deque`，两端操作都是 O(1)：

```python
from collections import deque

queue = deque()
queue.append('a')     # 入队
queue.append('b')
first = queue.popleft()   # 出队，返回 'a'
```

```cpp
void demo() {
    deque<char> queue;
    queue.push_back('a');        // 入队
    queue.push_back('b');
    char first = queue.front();  // 出队：先读队头 'a'……
    queue.pop_front();           // ……再删掉它，O(1)
}
```

```java
import java.util.*;

static void demo() {
    Deque<Character> queue = new ArrayDeque<>();
    queue.offer('a');            // 入队
    queue.offer('b');
    char first = queue.poll();   // 出队，返回 'a'
}
```

```go
import "fmt"

func demo() {
	queue := []byte{}
	queue = append(queue, 'a') // 入队
	queue = append(queue, 'b')
	first := queue[0]          // 出队：先读队头 'a'……
	queue = queue[1:]          // ……切片往后挪一格，O(1)
	fmt.Println(string(first), len(queue))
}
```

**什么时候想到队列？** 按到达顺序处理任务、广度优先搜索（BFS）、按层遍历树。

## 用两个栈实现队列

这是常见的面试题：一个栈 `inbox` 负责入队；出队时如果 `outbox` 为空，就把 `inbox` 的元素全部倒过去，顺序正好反过来。

```python
class MyQueue:
    def __init__(self):
        self.inbox, self.outbox = [], []

    def push(self, x):
        self.inbox.append(x)

    def peek(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())
        return self.outbox[-1]

    def pop(self):
        self.peek()
        return self.outbox.pop()

    def empty(self):
        return not self.inbox and not self.outbox
```

```cpp
class MyQueue {
    vector<int> inbox, outbox;

public:
    void push(int x) { inbox.push_back(x); }

    int peek() {
        if (outbox.empty())
            while (!inbox.empty()) {
                outbox.push_back(inbox.back());
                inbox.pop_back();
            }
        return outbox.back();
    }

    int pop() {
        int x = peek();
        outbox.pop_back();
        return x;
    }

    bool empty() { return inbox.empty() && outbox.empty(); }
};
```

```java
import java.util.*;

static class MyQueue {
    private final Deque<Integer> inbox = new ArrayDeque<>(), outbox = new ArrayDeque<>();

    void push(int x) { inbox.push(x); }

    int peek() {
        if (outbox.isEmpty())
            while (!inbox.isEmpty()) outbox.push(inbox.pop());
        return outbox.peek();
    }

    int pop() {
        peek();
        return outbox.pop();
    }

    boolean empty() { return inbox.isEmpty() && outbox.isEmpty(); }
}
```

```go
type MyQueue struct {
	inbox, outbox []int
}

func (q *MyQueue) Push(x int) { q.inbox = append(q.inbox, x) }

func (q *MyQueue) Peek() int {
	if len(q.outbox) == 0 {
		for len(q.inbox) > 0 {
			last := len(q.inbox) - 1
			q.outbox = append(q.outbox, q.inbox[last])
			q.inbox = q.inbox[:last]
		}
	}
	return q.outbox[len(q.outbox)-1]
}

func (q *MyQueue) Pop() int {
	x := q.Peek()
	q.outbox = q.outbox[:len(q.outbox)-1]
	return x
}

func (q *MyQueue) Empty() bool { return len(q.inbox) == 0 && len(q.outbox) == 0 }
```

单次 `pop` 可能要倒腾很多元素，但**每个元素一生只会从 inbox 搬到 outbox 一次**，所以均摊下来每个操作都是 O(1)。

栈还有一个进阶用法：单调栈。让栈里的值保持单调，每个元素只进栈、出栈各一次，就能在 O(n) 内求出每个数右边第一个更大的数。后面的单调栈专题会细讲。

```algorithm-demo
monotonic-stack
```

## 小结

| 结构 | 规则 | Python 写法 | 典型用途 |
|---|---|---|---|
| 栈 | 后进先出 | `list` 的 `append` / `pop` | 括号匹配、DFS、撤销 |
| 队列 | 先进先出 | `deque` 的 `append` / `popleft` | BFS、按顺序处理 |

看到题目里有“配对”“嵌套”“最近的”这类字眼，先想栈；看到“按层”“最短步数”“先来先处理”，先想队列。

