Stacks and queues are sequences you can only enter and leave at specific ends. The extra rules make them harder to misuse, not easier.

```mermaid
flowchart LR
  accTitle: A stack goes in and out at the same end; a queue goes in at the back and out at the front
  subgraph S["Stack: append and pop at the top"]
    direction LR
    s1["1"] --- s2["2"] --- s3["3 (top)"]
  end
  subgraph Q["Queue: append at the back, popleft at the front"]
    direction LR
    q1["1 (front)"] --- q2["2"] --- q3["3 (back)"]
  end
  push(["push 4"]) --> s3
  s3 --> pop(["pop gives 3"])
  enq(["append 4"]) --> q3
  q1 --> deq(["popleft gives 1"])
```

## Stacks: last in, first out (LIFO)

A stack is like a pile of plates: you put on top and take from the top. In Python a plain `list` is a stack:

```python
stack = []
stack.append(1)    # push, O(1)
stack.append(2)
top = stack[-1]    # peek, O(1)
stack.pop()        # pop, returns 2, O(1)
```

```cpp
void demo() {
    vector<int> stack;
    stack.push_back(1);      // push, O(1)
    stack.push_back(2);
    int top = stack.back();  // peek, O(1)
    stack.pop_back();        // pop, O(1); C++'s pop returns nothing
}
```

```java
import java.util.*;

static void demo() {
    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(1);           // push, O(1)
    stack.push(2);
    int top = stack.peek();  // peek, O(1)
    stack.pop();             // pop, returns 2, O(1)
}
```

```go
import "fmt"

func demo() {
	stack := []int{}
	stack = append(stack, 1)     // push, O(1)
	stack = append(stack, 2)
	top := stack[len(stack)-1]   // peek, O(1)
	stack = stack[:len(stack)-1] // pop, O(1)
	fmt.Println(top, stack)      // 2 [1]
}
```

**When does a stack fit?** Whenever the most recent thing must be handled first: matching brackets, undo, the function call stack, depth-first search, and the monotonic stack you will meet later.

### Example: valid parentheses

Push every opening bracket. A closing bracket must match **the most recent opening bracket that is still unmatched**, which is exactly the top of the stack:

```python
def is_valid(s):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in s:
        if ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            stack.append(ch)
    return not stack   # no unmatched opening brackets may remain
```

```cpp
bool isValid(const string& s) {
    unordered_map<char, char> pairs = {{')', '('}, {']', '['}, {'}', '{'}};
    vector<char> stack;
    for (char ch : s) {
        if (pairs.count(ch)) {
            if (stack.empty() || stack.back() != pairs[ch]) return false;
            stack.pop_back();
        } else {
            stack.push_back(ch);
        }
    }
    return stack.empty();  // no unmatched opening brackets may remain
}
```

```java
import java.util.*;

static boolean isValid(String s) {
    Map<Character, Character> pairs = Map.of(')', '(', ']', '[', '}', '{');
    Deque<Character> stack = new ArrayDeque<>();
    for (char ch : s.toCharArray()) {
        if (pairs.containsKey(ch)) {
            char open = pairs.get(ch);
            if (stack.isEmpty() || stack.pop() != open) return false;
        } else {
            stack.push(ch);
        }
    }
    return stack.isEmpty();  // no unmatched opening brackets may remain
}
```

```go
func isValid(s string) bool {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	stack := []rune{}
	for _, ch := range s {
		if open, ok := pairs[ch]; ok {
			if len(stack) == 0 || stack[len(stack)-1] != open {
				return false
			}
			stack = stack[:len(stack)-1]
		} else {
			stack = append(stack, ch)
		}
	}
	return len(stack) == 0 // no unmatched opening brackets may remain
}
```

Each character is pushed and popped at most once: O(n) time, O(n) space.

## Queues: first in, first out (FIFO)

A queue is a line: join at the back, leave from the front. **Don't dequeue with `list.pop(0)`**: it shifts every remaining element forward, which is O(n). Use `collections.deque`, where both ends are O(1):

```python
from collections import deque

queue = deque()
queue.append('a')         # enqueue
queue.append('b')
first = queue.popleft()   # dequeue, returns 'a'
```

```cpp
void demo() {
    deque<char> queue;
    queue.push_back('a');        // enqueue
    queue.push_back('b');
    char first = queue.front();  // dequeue: read the front, 'a'…
    queue.pop_front();           // …then drop it, O(1)
}
```

```java
import java.util.*;

static void demo() {
    Deque<Character> queue = new ArrayDeque<>();
    queue.offer('a');            // enqueue
    queue.offer('b');
    char first = queue.poll();   // dequeue, returns 'a'
}
```

```go
import "fmt"

func demo() {
	queue := []byte{}
	queue = append(queue, 'a') // enqueue
	queue = append(queue, 'b')
	first := queue[0]          // dequeue: read the front, 'a'…
	queue = queue[1:]          // …the slice moves past it, O(1)
	fmt.Println(string(first), len(queue))
}
```

**When does a queue fit?** Processing tasks in arrival order, breadth-first search (BFS), and walking a tree level by level.

## A queue from two stacks

A classic interview question: the `inbox` stack takes every push. To dequeue, if `outbox` is empty, pour everything from `inbox` into it, which reverses the order.

```python
class MyQueue:
    def __init__(self):
        self.inbox, self.outbox = [], []

    def push(self, x):
        self.inbox.append(x)

    def peek(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())
        return self.outbox[-1]

    def pop(self):
        self.peek()
        return self.outbox.pop()

    def empty(self):
        return not self.inbox and not self.outbox
```

```cpp
class MyQueue {
    vector<int> inbox, outbox;

public:
    void push(int x) { inbox.push_back(x); }

    int peek() {
        if (outbox.empty())
            while (!inbox.empty()) {
                outbox.push_back(inbox.back());
                inbox.pop_back();
            }
        return outbox.back();
    }

    int pop() {
        int x = peek();
        outbox.pop_back();
        return x;
    }

    bool empty() { return inbox.empty() && outbox.empty(); }
};
```

```java
import java.util.*;

static class MyQueue {
    private final Deque<Integer> inbox = new ArrayDeque<>(), outbox = new ArrayDeque<>();

    void push(int x) { inbox.push(x); }

    int peek() {
        if (outbox.isEmpty())
            while (!inbox.isEmpty()) outbox.push(inbox.pop());
        return outbox.peek();
    }

    int pop() {
        peek();
        return outbox.pop();
    }

    boolean empty() { return inbox.isEmpty() && outbox.isEmpty(); }
}
```

```go
type MyQueue struct {
	inbox, outbox []int
}

func (q *MyQueue) Push(x int) { q.inbox = append(q.inbox, x) }

func (q *MyQueue) Peek() int {
	if len(q.outbox) == 0 {
		for len(q.inbox) > 0 {
			last := len(q.inbox) - 1
			q.outbox = append(q.outbox, q.inbox[last])
			q.inbox = q.inbox[:last]
		}
	}
	return q.outbox[len(q.outbox)-1]
}

func (q *MyQueue) Pop() int {
	x := q.Peek()
	q.outbox = q.outbox[:len(q.outbox)-1]
	return x
}

func (q *MyQueue) Empty() bool { return len(q.inbox) == 0 && len(q.outbox) == 0 }
```

A single `pop` may move many elements, but **each element moves from inbox to outbox only once in its lifetime**, so every operation is O(1) amortized.

One more stack pattern is the monotonic stack. Keep the values on the stack in order, push and pop each element once, and you get every value’s next greater element in O(n). It gets its own topic later.

```algorithm-demo
monotonic-stack
```

## Recap

| Structure | Rule | In Python | Typical use |
|---|---|---|---|
| Stack | last in, first out | `list` with `append` / `pop` | brackets, DFS, undo |
| Queue | first in, first out | `deque` with `append` / `popleft` | BFS, in-order processing |

Words like "matching", "nested" or "most recent" suggest a stack; "level by level", "fewest steps" or "first come, first served" suggest a queue.

chapters.bodyZh:
哈希表能在平均 O(1) 时间内完成“插入、删除、查找”，是面试里最常用的提速工具。Python 的 `dict` 和 `set` 都是哈希表。

## 它是怎么做到 O(1) 的

哈希表底层是一个数组。存一个键时，先用**哈希函数**把键算成一个整数，再对数组长度取模，得到它该放的位置：

```
位置 = hash(key) % 数组长度
```

查找时用同样的方法算出位置，直接去那里找，不用扫描整个表。

**冲突**：两个不同的键可能算出同一个位置。常见的解决办法有两种：每个位置挂一个链表（拉链法），或者往后找下一个空位（开放寻址，CPython 的 dict 用的是这种思路的变体）。只要元素填得不太满，冲突很少，平均仍是 O(1)。表快满时，哈希表会扩容并重新放置所有元素，这和列表扩容一样，均摊下来不影响 O(1)。

```mermaid
flowchart LR
  accTitle: 拉链法：hash(key) % 4 选出位置，冲突的键挂在同一个位置的链表上
  cat["'cat'"] -->|"hash % 4 = 1"| b1
  owl["'owl'"] -->|"hash % 4 = 1"| b1
  dog["'dog'"] -->|"hash % 4 = 3"| b3
  subgraph T["长度为 4 的数组"]
    b0["0：空"]
    b1["1"]
    b2["2：空"]
    b3["3"]
  end
  b1 --> c1["'cat'"] --> c2["'owl'"]
  b3 --> d1["'dog'"]
```

**最坏情况**：如果所有键都冲突到同一处，查找退化成 O(n)。日常做题不用担心，但面试时说出“平均 O(1)，最坏 O(n)”会更严谨。

演示用的是拉链法：键 k 放进第 k mod 桶数 号桶，冲突的键串成链表；负载因子（键数 ÷ 桶数）超过 0.75 时，桶数翻倍，所有键重新计算位置。

```algorithm-demo
hash-table
```

## 键必须是可哈希的

只有**不可变**的对象才能当字典的键或放进集合：`int`、`str`、`tuple`（元素也都不可变时）都可以，`list`、`dict`、`set` 不行。想用一个列表当键时，先转成元组：

```python
seen = set()
seen.add((1, 2))       # 可以
# seen.add([1, 2])     # TypeError: unhashable type: 'list'
```

```cpp
void demo() {
    set<pair<int, int>> seen;      // 有序集合只要元素能比较大小，pair 可以
    seen.insert({1, 2});
    // unordered_set<pair<int, int>> bad;  // 编译错误：标准库没有 pair 的哈希函数
}
```

```java
import java.util.*;

static void demo() {
    Set<List<Integer>> seen = new HashSet<>();
    seen.add(List.of(1, 2));                           // 可以：List 按内容算哈希
    Set<int[]> arrays = new HashSet<>();
    arrays.add(new int[] {1, 2});
    boolean found = arrays.contains(new int[] {1, 2});  // false：数组按地址算哈希，不能当键
}
```

```go
import "fmt"

func demo() {
	seen := map[[2]int]bool{}
	seen[[2]int{1, 2}] = true  // 可以：数组能比较
	// bad := map[[]int]bool{} // 编译错误：切片不能当键
	fmt.Println(len(seen))
}
```

## 四种常见用法

**1. 查“见过没有”**：用 `set`，`x in seen` 平均 O(1)，而对列表做 `x in lst` 是 O(n)。

**2. 计数**：

```python
count = {}
for ch in "banana":
    count[ch] = count.get(ch, 0) + 1
# {'b': 1, 'a': 3, 'n': 2}
```

```cpp
void demo() {
    unordered_map<char, int> count;
    for (char ch : string("banana"))
        count[ch]++;  // 不存在的键先默认为 0
    // b: 1, a: 3, n: 2
}
```

```java
import java.util.*;

static void demo() {
    Map<Character, Integer> count = new HashMap<>();
    for (char ch : "banana".toCharArray())
        count.merge(ch, 1, Integer::sum);  // 没有就放 1，有就加 1
    // {a=3, b=1, n=2}
}
```

```go
import "fmt"

func demo() {
	count := map[rune]int{}
	for _, ch := range "banana" {
		count[ch]++ // 不存在的键读出来是 0
	}
	fmt.Println(count['b'], count['a'], count['n']) // 1 3 2
}
```

**3. 值到下标的映射**：两数之和的标准解法。

```python
def two_sum(nums, target):
    seen = {}                       # 值 -> 下标
    for i, x in enumerate(nums):
        if target - x in seen:      # 先查
            return [seen[target - x], i]
        seen[x] = i                 # 后存
```

```cpp
vector<int> twoSum(const vector<int>& nums, int target) {
    unordered_map<int, int> seen;                // 值 -> 下标
    for (int i = 0; i < (int)nums.size(); i++) {
        auto it = seen.find(target - nums[i]);   // 先查
        if (it != seen.end()) return {it->second, i};
        seen[nums[i]] = i;                       // 后存
    }
    return {};
}
```

```java
import java.util.*;

static int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();  // 值 -> 下标
    for (int i = 0; i < nums.length; i++) {
        Integer j = seen.get(target - nums[i]);    // 先查
        if (j != null) return new int[] {j, i};
        seen.put(nums[i], i);                      // 后存
    }
    return new int[0];
}
```

```go
func twoSum(nums []int, target int) []int {
	seen := map[int]int{} // 值 -> 下标
	for i, x := range nums {
		if j, ok := seen[target-x]; ok { // 先查
			return []int{j, i}
		}
		seen[x] = i // 后存
	}
	return nil
}
```

先查再存，保证不会把同一个元素和它自己配成一对。

**4. 按“特征”分组**：把具有相同特征的元素放进同一个桶，比如字母异位词排序后相同，就用排序后的字符串当键。

## 例子：存在重复元素 II

判断是否存在两个相等的数，下标差不超过 k。用字典记住每个值**最近一次**出现的下标：

```python
def contains_nearby_duplicate(nums, k):
    last = {}
    for i, x in enumerate(nums):
        if x in last and i - last[x] <= k:
            return True
        last[x] = i
    return False
```

```cpp
bool containsNearbyDuplicate(const vector<int>& nums, int k) {
    unordered_map<int, int> last;
    for (int i = 0; i < (int)nums.size(); i++) {
        auto it = last.find(nums[i]);
        if (it != last.end() && i - it->second <= k) return true;
        last[nums[i]] = i;
    }
    return false;
}
```

```java
import java.util.*;

static boolean containsNearbyDuplicate(int[] nums, int k) {
    Map<Integer, Integer> last = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        Integer j = last.get(nums[i]);
        if (j != null && i - j <= k) return true;
        last.put(nums[i], i);
    }
    return false;
}
```

```go
func containsNearbyDuplicate(nums []int, k int) bool {
	last := map[int]int{}
	for i, x := range nums {
		if j, ok := last[x]; ok && i-j <= k {
			return true
		}
		last[x] = i
	}
	return false
}
```

时间 O(n)，空间 O(n)。

## 小结

- dict / set 的查找、插入、删除平均 O(1)，最坏 O(n)。
- 键要可哈希：列表先转元组。
- 看到“是否存在”“出现几次”“配对”“分组”，先想哈希表。

chapters.bodyEn:
A hash table inserts, deletes and looks up in O(1) on average, which makes it the most common speed-up in interviews. Python's `dict` and `set` are both hash tables.

## How it gets to O(1)

Underneath, a hash table is an array. To store a key, a **hash function** turns the key into an integer, and taking it modulo the array length gives the slot:

```
slot = hash(key) % array_length
```

A lookup computes the same slot and goes straight there instead of scanning the table.

**Collisions**: two different keys can land in the same slot. The two usual fixes are a small list per slot (chaining) or probing for the next free slot (open addressing; CPython's dict uses a variant of this). As long as the table isn't too full, collisions are rare and operations stay O(1) on average. When it fills up, the table grows and re-places every element; like list growth, that cost is amortized away.

```mermaid
flowchart LR
  accTitle: Chaining: hash(key) % 4 picks the slot, and colliding keys share that slot's list
  cat["'cat'"] -->|"hash % 4 = 1"| b1
  owl["'owl'"] -->|"hash % 4 = 1"| b1
  dog["'dog'"] -->|"hash % 4 = 3"| b3
  subgraph T["an array of 4 slots"]
    b0["0: empty"]
    b1["1"]
    b2["2: empty"]
    b3["3"]
  end
  b1 --> c1["'cat'"] --> c2["'owl'"]
  b3 --> d1["'dog'"]
```

**Worst case**: if every key collides into one place, a lookup degrades to O(n). You won't hit this in practice problems, but saying "O(1) on average, O(n) worst case" in an interview is more precise.

The demo uses chaining: key k goes to bucket k mod (bucket count), and colliding keys form a chain. Once the load factor (keys ÷ buckets) passes 0.75, the bucket count doubles and every key is placed again.

```algorithm-demo
hash-table
```

## Keys must be hashable

Only **immutable** objects can be dictionary keys or set members: `int`, `str` and `tuple` (of immutable items) work; `list`, `dict` and `set` don't. To use a list as a key, convert it to a tuple:

```python
seen = set()
seen.add((1, 2))       # fine
# seen.add([1, 2])     # TypeError: unhashable type: 'list'
```

```cpp
void demo() {
    set<pair<int, int>> seen;      // an ordered set only needs elements that compare: pairs are fine
    seen.insert({1, 2});
    // unordered_set<pair<int, int>> bad;  // compile error: the library has no hash for pair
}
```

```java
import java.util.*;

static void demo() {
    Set<List<Integer>> seen = new HashSet<>();
    seen.add(List.of(1, 2));                           // fine: a List hashes by its contents
    Set<int[]> arrays = new HashSet<>();
    arrays.add(new int[] {1, 2});
    boolean found = arrays.contains(new int[] {1, 2});  // false: arrays hash by identity, so they make poor keys
}
```

```go
import "fmt"

func demo() {
	seen := map[[2]int]bool{}
	seen[[2]int{1, 2}] = true  // fine: arrays are comparable
	// bad := map[[]int]bool{} // compile error: a slice cannot be a key
	fmt.Println(len(seen))
}
```

## Four everyday uses

**1. "Have I seen it?"**: use a `set`. `x in seen` is O(1) on average, while `x in lst` on a list is O(n).

**2. Counting**:

```python
count = {}
for ch in "banana":
    count[ch] = count.get(ch, 0) + 1
# {'b': 1, 'a': 3, 'n': 2}
```

```cpp
void demo() {
    unordered_map<char, int> count;
    for (char ch : string("banana"))
        count[ch]++;  // a missing key starts at 0
    // b: 1, a: 3, n: 2
}
```

```java
import java.util.*;

static void demo() {
    Map<Character, Integer> count = new HashMap<>();
    for (char ch : "banana".toCharArray())
        count.merge(ch, 1, Integer::sum);  // 1 if missing, else add 1
    // {a=3, b=1, n=2}
}
```

```go
import "fmt"

func demo() {
	count := map[rune]int{}
	for _, ch := range "banana" {
		count[ch]++ // a missing key reads as 0
	}
	fmt.Println(count['b'], count['a'], count['n']) // 1 3 2
}
```

**3. Value-to-index maps**: the standard Two Sum solution.

```python
def two_sum(nums, target):
    seen = {}                       # value -> index
    for i, x in enumerate(nums):
        if target - x in seen:      # look up first
            return [seen[target - x], i]
        seen[x] = i                 # then store
```

```cpp
vector<int> twoSum(const vector<int>& nums, int target) {
    unordered_map<int, int> seen;                // value -> index
    for (int i = 0; i < (int)nums.size(); i++) {
        auto it = seen.find(target - nums[i]);   // look up first
        if (it != seen.end()) return {it->second, i};
        seen[nums[i]] = i;                       // then store
    }
    return {};
}
```

```java
import java.util.*;

static int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();  // value -> index
    for (int i = 0; i < nums.length; i++) {
        Integer j = seen.get(target - nums[i]);    // look up first
        if (j != null) return new int[] {j, i};
        seen.put(nums[i], i);                      // then store
    }
    return new int[0];
}
```

```go
func twoSum(nums []int, target int) []int {
	seen := map[int]int{} // value -> index
	for i, x := range nums {
		if j, ok := seen[target-x]; ok { // look up first
			return []int{j, i}
		}
		seen[x] = i // then store
	}
	return nil
}
```

Looking up before storing guarantees an element is never paired with itself.

**4. Grouping by a signature**: put elements that share a feature into the same bucket. Anagrams, for example, are equal once sorted, so the sorted string is the key.

## Example: Contains Duplicate II

Decide whether two equal numbers sit at most k indices apart. Remember the **most recent** index of each value:

```python
def contains_nearby_duplicate(nums, k):
    last = {}
    for i, x in enumerate(nums):
        if x in last and i - last[x] <= k:
            return True
        last[x] = i
    return False
```

```cpp
bool containsNearbyDuplicate(const vector<int>& nums, int k) {
    unordered_map<int, int> last;
    for (int i = 0; i < (int)nums.size(); i++) {
        auto it = last.find(nums[i]);
        if (it != last.end() && i - it->second <= k) return true;
        last[nums[i]] = i;
    }
    return false;
}
```

```java
import java.util.*;

static boolean containsNearbyDuplicate(int[] nums, int k) {
    Map<Integer, Integer> last = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        Integer j = last.get(nums[i]);
        if (j != null && i - j <= k) return true;
        last.put(nums[i], i);
    }
    return false;
}
```

```go
func containsNearbyDuplicate(nums []int, k int) bool {
	last := map[int]int{}
	for i, x := range nums {
		if j, ok := last[x]; ok && i-j <= k {
			return true
		}
		last[x] = i
	}
	return false
}
```

O(n) time, O(n) space.

## Recap

- dict and set operations are O(1) on average and O(n) in the worst case.
- Keys must be hashable: turn lists into tuples.
- "Does it exist", "how many times", "find the pair" and "group these" all point to a hash table.

chapters.bodyZh:
树是有层次的结构：一个**根**结点，每个结点下面挂着若干**子结点**，没有子结点的叫**叶子**。面试里最常见的是**二叉树**，每个结点最多两个孩子。

```mermaid
flowchart TD
  accTitle: 一棵二叉搜索树，根是 4
  n4((4)) --> n2((2))
  n4 --> n6((6))
  n2 --> n1((1))
  n2 --> n3((3))
  n6 --> n5((5))
  n6 --> n7((7))
```

```python
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val, self.left, self.right = val, left, right
```

```cpp
struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int val = 0, TreeNode* left = nullptr, TreeNode* right = nullptr)
        : val(val), left(left), right(right) {}
};
```

```java
static class TreeNode {
    int val;
    TreeNode left, right;

    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}
```

```go
type TreeNode struct {
	Val         int
	Left, Right *TreeNode
}
```

几个术语：结点的**深度**是从根到它经过的边数；树的**高度**是最深的叶子的深度。上图有 7 个结点，高度为 2。

## 深度优先遍历（DFS）

按“访问根”的时机不同，分三种顺序。以上图为例：

| 顺序 | 规则 | 结果 |
|---|---|---|
| 前序 | 根 → 左 → 右 | 4 2 1 3 6 5 7 |
| 中序 | 左 → 根 → 右 | 1 2 3 4 5 6 7 |
| 后序 | 左 → 右 → 根 | 1 3 2 5 7 6 4 |

递归写法几乎就是规则本身：

```python
def inorder(root, out):
    if root is None:
        return
    inorder(root.left, out)
    out.append(root.val)      # 挪到前面就是前序，挪到最后就是后序
    inorder(root.right, out)
```

```cpp
struct TreeNode { int val; TreeNode *left, *right; };  // 定义见上

void inorder(TreeNode* root, vector<int>& out) {
    if (!root) return;
    inorder(root->left, out);
    out.push_back(root->val);  // 挪到前面就是前序，挪到最后就是后序
    inorder(root->right, out);
}
```

```java
import java.util.*;

static class TreeNode { int val; TreeNode left, right; }  // 定义见上

static void inorder(TreeNode root, List<Integer> out) {
    if (root == null) return;
    inorder(root.left, out);
    out.add(root.val);  // 挪到前面就是前序，挪到最后就是后序
    inorder(root.right, out);
}
```

```go
type TreeNode struct{ Val int; Left, Right *TreeNode } // 定义见上

func inorder(root *TreeNode, out *[]int) {
	if root == nil {
		return
	}
	inorder(root.Left, out)
	*out = append(*out, root.Val) // 挪到前面就是前序，挪到最后就是后序
	inorder(root.Right, out)
}
```

很多树的题都可以用“**相信递归**”的思路：假设函数对左右子树已经算对了，只考虑怎么用两个子结果拼出当前结点的答案。比如最大深度：

```python
def max_depth(root):
    if root is None:
        return 0
    return 1 + max(max_depth(root.left), max_depth(root.right))
```

```cpp
struct TreeNode { int val; TreeNode *left, *right; };  // 定义见上

int maxDepth(TreeNode* root) {
    if (!root) return 0;
    return 1 + max(maxDepth(root->left), maxDepth(root->right));
}
```

```java
static class TreeNode { int val; TreeNode left, right; }  // 定义见上

static int maxDepth(TreeNode root) {
    if (root == null) return 0;
    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}
```

```go
type TreeNode struct{ Val int; Left, Right *TreeNode } // 定义见上

func maxDepth(root *TreeNode) int {
	if root == nil {
		return 0
	}
	return 1 + max(maxDepth(root.Left), maxDepth(root.Right))
}
```

翻转二叉树也一样：交换左右孩子，再分别翻转两棵子树。

## 广度优先遍历（BFS）：一层一层走

用队列按层访问。每轮先记下当前队列长度，就能把同一层的结点分到一组：

```python
from collections import deque

def level_order(root):
    if root is None:
        return []
    levels, queue = [], deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):    # 只处理当前这一层
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        levels.append(level)
    return levels
```

```cpp
struct TreeNode { int val; TreeNode *left, *right; };  // 定义见上

vector<vector<int>> levelOrder(TreeNode* root) {
    if (!root) return {};
    vector<vector<int>> levels;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        vector<int> level;
        for (int n = q.size(); n > 0; n--) {  // 只处理当前这一层
            TreeNode* node = q.front();
            q.pop();
            level.push_back(node->val);
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        levels.push_back(level);
    }
    return levels;
}
```

```java
import java.util.*;

static class TreeNode { int val; TreeNode left, right; }  // 定义见上

static List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> levels = new ArrayList<>();
    if (root == null) return levels;
    Deque<TreeNode> queue = new ArrayDeque<>(List.of(root));
    while (!queue.isEmpty()) {
        List<Integer> level = new ArrayList<>();
        for (int n = queue.size(); n > 0; n--) {  // 只处理当前这一层
            TreeNode node = queue.poll();
            level.add(node.val);
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        levels.add(level);
    }
    return levels;
}
```

```go
type TreeNode struct{ Val int; Left, Right *TreeNode } // 定义见上

func levelOrder(root *TreeNode) [][]int {
	if root == nil {
		return nil
	}
	levels, queue := [][]int{}, []*TreeNode{root}
	for len(queue) > 0 {
		level := []int{}
		for n := len(queue); n > 0; n-- { // 只处理当前这一层
			node := queue[0]
			queue = queue[1:]
			level = append(level, node.Val)
			if node.Left != nil {
				queue = append(queue, node.Left)
			}
			if node.Right != nil {
				queue = append(queue, node.Right)
			}
		}
		levels = append(levels, level)
	}
	return levels
}
```

上图的结果是 `[[4], [2, 6], [1, 3, 5, 7]]`。

下面用同一棵树演示四种遍历：前三种用一个栈代替递归，层序用队列。

```algorithm-demo
tree-traversal
```

## 二叉搜索树（BST）

BST 满足：每个结点左子树的值都比它小，右子树的值都比它大。所以**中序遍历 BST 得到升序序列**。查找时每一步都能丢掉一半子树，树平衡时是 O(log n)；但如果数据按顺序插入，树会退化成一条链，变成 O(n)。

演示 BST 的查找、插入和删除。删除分三种情况：叶子直接删；只有一个孩子，就让孩子顶上来；有两个孩子，就用右子树里最小的结点（中序后继）顶替它。

```algorithm-demo
bst
```

## 复杂度

遍历每个结点一次，时间 O(n)。递归的额外空间是调用栈的深度 O(h)，h 是树高：平衡树约 log n，退化成链时是 n。BFS 的队列最多同时装下一整层的结点。

## 小结

- 三种 DFS 顺序只差在“什么时候访问根”。
- 树的递归题：想清楚空结点返回什么，以及怎么合并左右子树的结果。
- 要按层处理、或求离根最近的某个结点，用 BFS。

