}
```

Some terms: a node's **depth** is the number of edges from the root to it; a tree's **height** is the depth of its deepest leaf. The tree above has 7 nodes and height 2.

## Depth-first traversal (DFS)

The three orders differ only in when the root is visited. For the tree above:

| Order | Rule | Result |
|---|---|---|
| Preorder | root → left → right | 4 2 1 3 6 5 7 |
| Inorder | left → root → right | 1 2 3 4 5 6 7 |
| Postorder | left → right → root | 1 3 2 5 7 6 4 |

The recursive code is almost the rule itself:

```python
def inorder(root, out):
    if root is None:
        return
    inorder(root.left, out)
    out.append(root.val)      # move it first for preorder, last for postorder
    inorder(root.right, out)
```

```cpp
struct TreeNode { int val; TreeNode *left, *right; };  // defined above

void inorder(TreeNode* root, vector<int>& out) {
    if (!root) return;
    inorder(root->left, out);
    out.push_back(root->val);  // move it first for preorder, last for postorder
    inorder(root->right, out);
}
```

```java
import java.util.*;

static class TreeNode { int val; TreeNode left, right; }  // defined above

static void inorder(TreeNode root, List<Integer> out) {
    if (root == null) return;
    inorder(root.left, out);
    out.add(root.val);  // move it first for preorder, last for postorder
    inorder(root.right, out);
}
```

```go
type TreeNode struct{ Val int; Left, Right *TreeNode } // defined above

func inorder(root *TreeNode, out *[]int) {
	if root == nil {
		return
	}
	inorder(root.Left, out)
	*out = append(*out, root.Val) // move it first for preorder, last for postorder
	inorder(root.Right, out)
}
```

Many tree problems yield to **trusting the recursion**: assume the function already returns the right answer for the left and right subtrees, and only decide how to combine those two results at the current node. Maximum depth, for example:

```python
def max_depth(root):
    if root is None:
        return 0
    return 1 + max(max_depth(root.left), max_depth(root.right))
```

```cpp
struct TreeNode { int val; TreeNode *left, *right; };  // defined above

int maxDepth(TreeNode* root) {
    if (!root) return 0;
    return 1 + max(maxDepth(root->left), maxDepth(root->right));
}
```

```java
static class TreeNode { int val; TreeNode left, right; }  // defined above

static int maxDepth(TreeNode root) {
    if (root == null) return 0;
    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}
```

```go
type TreeNode struct{ Val int; Left, Right *TreeNode } // defined above

func maxDepth(root *TreeNode) int {
	if root == nil {
		return 0
	}
	return 1 + max(maxDepth(root.Left), maxDepth(root.Right))
}
```

Inverting a tree works the same way: swap the two children, then invert each subtree.

## Breadth-first traversal (BFS): level by level

A queue visits nodes level by level. Recording the queue length at the start of each round groups the nodes of one level together:

```python
from collections import deque

def level_order(root):
    if root is None:
        return []
    levels, queue = [], deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):    # only this level's nodes
            node = queue.popleft()
            level.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        levels.append(level)
    return levels
```

```cpp
struct TreeNode { int val; TreeNode *left, *right; };  // defined above

vector<vector<int>> levelOrder(TreeNode* root) {
    if (!root) return {};
    vector<vector<int>> levels;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        vector<int> level;
        for (int n = q.size(); n > 0; n--) {  // only this level's nodes
            TreeNode* node = q.front();
            q.pop();
            level.push_back(node->val);
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        levels.push_back(level);
    }
    return levels;
}
```

```java
import java.util.*;

static class TreeNode { int val; TreeNode left, right; }  // defined above

static List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> levels = new ArrayList<>();
    if (root == null) return levels;
    Deque<TreeNode> queue = new ArrayDeque<>(List.of(root));
    while (!queue.isEmpty()) {
        List<Integer> level = new ArrayList<>();
        for (int n = queue.size(); n > 0; n--) {  // only this level's nodes
            TreeNode node = queue.poll();
            level.add(node.val);
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        levels.add(level);
    }
    return levels;
}
```

```go
type TreeNode struct{ Val int; Left, Right *TreeNode } // defined above

func levelOrder(root *TreeNode) [][]int {
	if root == nil {
		return nil
	}
	levels, queue := [][]int{}, []*TreeNode{root}
	for len(queue) > 0 {
		level := []int{}
		for n := len(queue); n > 0; n-- { // only this level's nodes
			node := queue[0]
			queue = queue[1:]
			level = append(level, node.Val)
			if node.Left != nil {
				queue = append(queue, node.Left)
			}
			if node.Right != nil {
				queue = append(queue, node.Right)
			}
		}
		levels = append(levels, level)
	}
	return levels
}
```

For the tree above it returns `[[4], [2, 6], [1, 3, 5, 7]]`.

The demo walks one tree in all four orders: the first three replace the recursion with a stack, level order uses a queue.

```algorithm-demo
tree-traversal
```

## Binary search trees (BST)

In a BST every value in a node's left subtree is smaller than the node and every value in its right subtree is larger. So **an inorder traversal of a BST is sorted**. A search discards one subtree at each step: O(log n) when the tree is balanced, but if values are inserted in sorted order the tree degenerates into a chain and search becomes O(n).

The demo runs find, insert and delete on a BST. Deleting has three cases: a leaf simply goes; a node with one child is replaced by that child; a node with two children is replaced by the smallest node of its right subtree, its in-order successor.

```algorithm-demo
bst
```

## Complexity

Traversal visits each node once: O(n) time. Recursion uses stack space equal to the depth, O(h) for height h: about log n for a balanced tree, n for a chain. A BFS queue holds at most one full level at a time.

## Recap

- The three DFS orders differ only in when the root is visited.
- For recursive tree problems, decide what an empty node returns and how to combine the two subtree results.
- To work level by level, or to find the node closest to the root, use BFS.

chapters.bodyZh:
堆专门回答一个问题：**当前最小（或最大）的元素是谁？**它能在 O(1) 时间看到最小值，在 O(log n) 时间取出最小值或放进新元素。

## 结构：用数组存的完全二叉树

**最小堆**满足：每个结点都不大于它的孩子，所以根就是最小值。堆是一棵**完全二叉树**（除最后一层外都填满，最后一层从左往右填），因此可以直接存在数组里，不需要指针：下标 i 的孩子在 `2i + 1` 和 `2i + 2`，父结点在 `(i - 1) // 2`。

数组 `[1, 3, 2, 7, 4, 5]` 对应的树：

```mermaid
flowchart TD
  accTitle: 数组 1 3 2 7 4 5 表示的最小堆
  a((1)) --> b((3))
  a --> c((2))
  b --> d((7))
  b --> e((4))
  c --> f((5))
```

注意堆**只保证父子之间的大小关系**，兄弟之间没有顺序，所以堆不是排好序的数组。

## 两个核心操作

- **插入**：放到数组末尾，再和父结点比较，比父结点小就交换，一路往上“冒泡”。最多走树高 O(log n) 步。
- **弹出最小值**：取走根，把最后一个元素挪到根的位置，再和较小的孩子比较、往下“下沉”。同样 O(log n)。

把一个任意数组整理成堆（heapify）只需要 O(n)，比逐个插入的 O(n log n) 更快。

## Python 的 heapq

`heapq` 直接在普通列表上操作，提供的是**最小堆**：

```python
import heapq

nums = [5, 1, 8, 3]
heapq.heapify(nums)          # O(n)，nums 现在满足堆性质
heapq.heappush(nums, 2)      # O(log n)
smallest = heapq.heappop(nums)   # 返回 1，O(log n)
peek = nums[0]                   # 看最小值，O(1)
```

```cpp
void demo() {
    vector<int> nums = {5, 1, 8, 3};
    priority_queue<int, vector<int>, greater<int>> heap(nums.begin(), nums.end());  // 用 greater 是小顶堆，建堆 O(n)
    heap.push(2);               // O(log n)
    int smallest = heap.top();  // 1：C++ 先读堆顶……
    heap.pop();                 // ……再弹出，O(log n)
    int peek = heap.top();      // 现在的最小值 2，O(1)
}
```

```java
import java.util.*;

static void demo() {
    PriorityQueue<Integer> heap = new PriorityQueue<>(List.of(5, 1, 8, 3));  // 默认小顶堆，从集合建堆 O(n)
    heap.offer(2);                 // O(log n)
    int smallest = heap.poll();    // 返回 1，O(log n)
    int peek = heap.peek();        // 看最小值，O(1)
}
```

```go
import (
	"container/heap"
	"fmt"
)

// Go 的堆要自己实现 heap.Interface 的五个方法
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func demo() {
	h := &IntHeap{5, 1, 8, 3}
	heap.Init(h)                  // O(n)，h 现在满足堆性质
	heap.Push(h, 2)               // O(log n)
	smallest := heap.Pop(h).(int) // 返回 1，O(log n)
	peek := (*h)[0]               // 看最小值，O(1)
	fmt.Println(smallest, peek)
}
```

需要**最大堆**时，常用的办法是存相反数：

```python
def last_stone_weight(stones):
    heap = [-s for s in stones]   # 取负数，最小堆就成了最大堆
    heapq.heapify(heap)
    while len(heap) > 1:
        a = -heapq.heappop(heap)  # 最重的
        b = -heapq.heappop(heap)  # 第二重的
        if a != b:
            heapq.heappush(heap, -(a - b))
    return -heap[0] if heap else 0
```

```cpp
int lastStoneWeight(const vector<int>& stones) {
    priority_queue<int> heap(stones.begin(), stones.end());  // C++ 默认就是大顶堆，不用取负
    while (heap.size() > 1) {
        int a = heap.top();  // 最重的
        heap.pop();
        int b = heap.top();  // 第二重的
        heap.pop();
        if (a != b) heap.push(a - b);
    }
    return heap.empty() ? 0 : heap.top();
}
```

```java
import java.util.*;

static int lastStoneWeight(int[] stones) {
    PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());  // 反过来比较就是大顶堆
    for (int s : stones) heap.offer(s);
    while (heap.size() > 1) {
        int a = heap.poll();  // 最重的
        int b = heap.poll();  // 第二重的
        if (a != b) heap.offer(a - b);
    }
    return heap.isEmpty() ? 0 : heap.peek();
}
```

```go
import "container/heap"

// Less 用 >，就是大顶堆
type MaxHeap []int

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *MaxHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *MaxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func lastStoneWeight(stones []int) int {
	h := MaxHeap(append([]int(nil), stones...))
	heap.Init(&h)
	for h.Len() > 1 {
		a := heap.Pop(&h).(int) // 最重的
		b := heap.Pop(&h).(int) // 第二重的
		if a != b {
			heap.Push(&h, a-b)
		}
	}
	if h.Len() == 0 {
		return 0
	}
	return h[0]
}
```

## 经典套路：Top K

从 n 个数里找最大的 k 个，不必全排序。维护一个**大小为 k 的最小堆**：堆里始终是“目前最大的 k 个”，堆顶是其中最小的，也就是第 k 大。新来的数比堆顶大就替换进去。

```python
class KthLargest:
    def __init__(self, k, nums):
        self.k, self.heap = k, []
        for x in nums:
            self.add(x)

    def add(self, val):
        heapq.heappush(self.heap, val)
        if len(self.heap) > self.k:
            heapq.heappop(self.heap)   # 把第 k+1 大的扔掉
        return self.heap[0]
```

```cpp
class KthLargest {
    int k;
    priority_queue<int, vector<int>, greater<int>> heap;  // 小顶堆

public:
    KthLargest(int k, const vector<int>& nums) : k(k) {
        for (int x : nums) add(x);
    }

    int add(int val) {
        heap.push(val);
        if ((int)heap.size() > k) heap.pop();  // 把第 k+1 大的扔掉
        return heap.top();
    }
};
```

```java
import java.util.*;

static class KthLargest {
    private final int k;
    private final PriorityQueue<Integer> heap = new PriorityQueue<>();  // 小顶堆

    KthLargest(int k, int[] nums) {
        this.k = k;
        for (int x : nums) add(x);
    }

    int add(int val) {
        heap.offer(val);
        if (heap.size() > k) heap.poll();  // 把第 k+1 大的扔掉
        return heap.peek();
    }
}
```

```go
import "container/heap"

// Go 的堆要自己实现 heap.Interface 的五个方法
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

type KthLargest struct {
	k int
	h *IntHeap
}

func Constructor(k int, nums []int) KthLargest {
	kl := KthLargest{k: k, h: &IntHeap{}}
	for _, x := range nums {
		kl.Add(x)
	}
	return kl
}

func (kl *KthLargest) Add(val int) int {
	heap.Push(kl.h, val)
	if kl.h.Len() > kl.k {
		heap.Pop(kl.h) // 把第 k+1 大的扔掉
	}
	return (*kl.h)[0]
}
```

每个数进出堆一次，时间 O(n log k)，空间 O(k)。k 远小于 n 时，比排序的 O(n log n) 划算。

第一个演示用大小为 k 的小顶堆求数据流里的第 k 大。第二个是堆排序：先把数组建成大顶堆，再反复把堆顶换到末尾、让新的堆顶下沉。它原地完成、O(n log n)，但不稳定。

```algorithm-demo
heap
```

```algorithm-demo
sort-heap
```

## 小结

| 操作 | 复杂度 |
|---|---|
| 看最小值 `heap[0]` | O(1) |
| `heappush` / `heappop` | O(log n) |
| `heapify` | O(n) |

看到“第 k 大”“前 k 个”“每次取当前最小/最大”“合并多个有序序列”，就想到堆。

chapters.bodyEn:
A heap answers one question fast: **which element is currently the smallest (or largest)?** It shows the minimum in O(1) and removes it or adds a new element in O(log n).

## Structure: a complete binary tree in an array

A **min-heap** keeps every node no larger than its children, so the root is the minimum. A heap is a **complete binary tree** (every level full except the last, which fills left to right), so it fits in a plain array with no pointers: the children of index i are at `2i + 1` and `2i + 2`, and its parent is at `(i - 1) // 2`.

The array `[1, 3, 2, 7, 4, 5]` is this tree:

```mermaid
flowchart TD
  accTitle: The min-heap stored as the array 1 3 2 7 4 5
  a((1)) --> b((3))
  a --> c((2))
  b --> d((7))
  b --> e((4))
  c --> f((5))
```

A heap **only orders parents against children**; siblings have no order, so a heap is not a sorted array.

## The two core operations

- **Push**: append at the end, then compare with the parent and swap while it is smaller, bubbling up. At most the tree height, O(log n) steps.
- **Pop the minimum**: take the root, move the last element into its place, then swap it down with its smaller child. Also O(log n).

Turning an arbitrary array into a heap (heapify) takes O(n), faster than n pushes at O(n log n).

## Python's heapq

`heapq` works on ordinary lists and gives you a **min-heap**:

```python
import heapq

nums = [5, 1, 8, 3]
heapq.heapify(nums)              # O(n); nums now satisfies the heap property
heapq.heappush(nums, 2)          # O(log n)
smallest = heapq.heappop(nums)   # returns 1, O(log n)
peek = nums[0]                   # the minimum, O(1)
```

```cpp
void demo() {
    vector<int> nums = {5, 1, 8, 3};
    priority_queue<int, vector<int>, greater<int>> heap(nums.begin(), nums.end());  // greater makes a min-heap, built in O(n)
    heap.push(2);               // O(log n)
    int smallest = heap.top();  // 1: C++ reads the top…
    heap.pop();                 // …then pops it, O(log n)
    int peek = heap.top();      // the minimum now, 2, O(1)
}
```

```java
import java.util.*;

static void demo() {
    PriorityQueue<Integer> heap = new PriorityQueue<>(List.of(5, 1, 8, 3));  // a min-heap by default, built from a collection in O(n)
    heap.offer(2);                 // O(log n)
    int smallest = heap.poll();    // returns 1, O(log n)
    int peek = heap.peek();        // the minimum, O(1)
}
```

```go
import (
	"container/heap"
	"fmt"
)

// Go heaps implement the five methods of heap.Interface
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func demo() {
	h := &IntHeap{5, 1, 8, 3}
	heap.Init(h)                  // O(n); h now satisfies the heap property
	heap.Push(h, 2)               // O(log n)
	smallest := heap.Pop(h).(int) // returns 1, O(log n)
	peek := (*h)[0]               // the minimum, O(1)
	fmt.Println(smallest, peek)
}
```

For a **max-heap**, the usual trick is to store negated values:

```python
def last_stone_weight(stones):
    heap = [-s for s in stones]   # negate: the min-heap now acts as a max-heap
    heapq.heapify(heap)
    while len(heap) > 1:
        a = -heapq.heappop(heap)  # heaviest
        b = -heapq.heappop(heap)  # second heaviest
        if a != b:
            heapq.heappush(heap, -(a - b))
    return -heap[0] if heap else 0
```

```cpp
int lastStoneWeight(const vector<int>& stones) {
    priority_queue<int> heap(stones.begin(), stones.end());  // C++ defaults to a max-heap: no negating
    while (heap.size() > 1) {
        int a = heap.top();  // heaviest
        heap.pop();
        int b = heap.top();  // second heaviest
        heap.pop();
        if (a != b) heap.push(a - b);
    }
    return heap.empty() ? 0 : heap.top();
}
```

```java
import java.util.*;

static int lastStoneWeight(int[] stones) {
    PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());  // reversed order makes a max-heap
    for (int s : stones) heap.offer(s);
    while (heap.size() > 1) {
        int a = heap.poll();  // heaviest
        int b = heap.poll();  // second heaviest
        if (a != b) heap.offer(a - b);
    }
    return heap.isEmpty() ? 0 : heap.peek();
}
```

```go
import "container/heap"

// Less uses >, which makes a max-heap
type MaxHeap []int

func (h MaxHeap) Len() int           { return len(h) }
func (h MaxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h MaxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *MaxHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *MaxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func lastStoneWeight(stones []int) int {
	h := MaxHeap(append([]int(nil), stones...))
	heap.Init(&h)
	for h.Len() > 1 {
		a := heap.Pop(&h).(int) // heaviest
		b := heap.Pop(&h).(int) // second heaviest
		if a != b {
			heap.Push(&h, a-b)
		}
	}
	if h.Len() == 0 {
		return 0
	}
	return h[0]
}
```

## The classic pattern: top k

To find the k largest of n numbers you don't need a full sort. Keep a **min-heap of size k**: it always holds the k largest so far, and its top is the smallest of them, the k-th largest. A new number bigger than the top replaces it.

```python
class KthLargest:
    def __init__(self, k, nums):
        self.k, self.heap = k, []
        for x in nums:
            self.add(x)

    def add(self, val):
        heapq.heappush(self.heap, val)
        if len(self.heap) > self.k:
            heapq.heappop(self.heap)   # drop the (k+1)-th largest
        return self.heap[0]
```

```cpp
class KthLargest {
    int k;
    priority_queue<int, vector<int>, greater<int>> heap;  // min-heap

public:
    KthLargest(int k, const vector<int>& nums) : k(k) {
        for (int x : nums) add(x);
    }

    int add(int val) {
        heap.push(val);
        if ((int)heap.size() > k) heap.pop();  // drop the (k+1)-th largest
        return heap.top();
    }
};
```

```java
import java.util.*;

static class KthLargest {
    private final int k;
    private final PriorityQueue<Integer> heap = new PriorityQueue<>();  // min-heap

    KthLargest(int k, int[] nums) {
        this.k = k;
        for (int x : nums) add(x);
    }

    int add(int val) {
        heap.offer(val);
        if (heap.size() > k) heap.poll();  // drop the (k+1)-th largest
        return heap.peek();
    }
}
```

```go
import "container/heap"

// Go heaps implement the five methods of heap.Interface
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

type KthLargest struct {
	k int
	h *IntHeap
}

func Constructor(k int, nums []int) KthLargest {
	kl := KthLargest{k: k, h: &IntHeap{}}
	for _, x := range nums {
		kl.Add(x)
	}
	return kl
}

func (kl *KthLargest) Add(val int) int {
	heap.Push(kl.h, val)
	if kl.h.Len() > kl.k {
		heap.Pop(kl.h) // drop the (k+1)-th largest
	}
	return (*kl.h)[0]
}
```

Each number enters and leaves the heap once: O(n log k) time, O(k) space. When k is much smaller than n, that beats sorting at O(n log n).

The first demo keeps a size-k min-heap to track the k-th largest in a stream. The second is heapsort: build a max-heap, then keep swapping the root to the end and sifting the new root down. It works in place in O(n log n), but it is not stable.

