```

## 深度优先搜索（DFS）

沿着一条路一直走到底，走不通再回头。递归写起来最短，适合判断连通性、数连通块、找路径：

```python
def has_path(graph, source, target):
    seen = set()
    def dfs(u):
        if u == target:
            return True
        seen.add(u)
        return any(v not in seen and dfs(v) for v in graph[u])
    return dfs(source)
```

```cpp
bool hasPath(unordered_map<int, vector<int>>& graph, int source, int target) {
    unordered_set<int> seen;
    function<bool(int)> dfs = [&](int u) {
        if (u == target) return true;
        seen.insert(u);
        for (int v : graph[u])
            if (!seen.count(v) && dfs(v)) return true;
        return false;
    };
    return dfs(source);
}
```

```java
import java.util.*;

static boolean hasPath(Map<Integer, List<Integer>> graph, int source, int target) {
    return dfs(graph, source, target, new HashSet<>());
}

static boolean dfs(Map<Integer, List<Integer>> graph, int u, int target, Set<Integer> seen) {
    if (u == target) return true;
    seen.add(u);
    for (int v : graph.getOrDefault(u, List.of()))
        if (!seen.contains(v) && dfs(graph, v, target, seen)) return true;
    return false;
}
```

```go
func hasPath(graph map[int][]int, source, target int) bool {
	seen := map[int]bool{}
	var dfs func(u int) bool
	dfs = func(u int) bool {
		if u == target {
			return true
		}
		seen[u] = true
		for _, v := range graph[u] {
			if !seen[v] && dfs(v) {
				return true
			}
		}
		return false
	}
	return dfs(source)
}
```

图比较大时，Python 的递归深度上限（默认约 1000 层）可能不够，可以改用显式的栈，或者直接用 BFS。

## 网格就是图

二维网格里，每个格子是一个顶点，和上下左右四个格子相邻。图像渲染（flood fill）就是从一个格子出发，把相连的同色格子都染成新颜色：

```python
def flood_fill(image, sr, sc, color):
    old = image[sr][sc]
    if old == color:           # 不判断的话会反复染同一个格子
        return image
    rows, cols = len(image), len(image[0])
    def dfs(r, c):
        if 0 <= r < rows and 0 <= c < cols and image[r][c] == old:
            image[r][c] = color
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                dfs(r + dr, c + dc)
    dfs(sr, sc)
    return image
```

```cpp
vector<vector<int>> floodFill(vector<vector<int>> image, int sr, int sc, int color) {
    int old = image[sr][sc];
    if (old == color) return image;  // 不判断的话会反复染同一个格子
    int rows = image.size(), cols = image[0].size();
    function<void(int, int)> dfs = [&](int r, int c) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || image[r][c] != old) return;
        image[r][c] = color;
        for (auto [dr, dc] : {pair{1, 0}, pair{-1, 0}, pair{0, 1}, pair{0, -1}})
            dfs(r + dr, c + dc);
    };
    dfs(sr, sc);
    return image;
}
```

```java
static int[][] floodFill(int[][] image, int sr, int sc, int color) {
    int old = image[sr][sc];
    if (old == color) return image;  // 不判断的话会反复染同一个格子
    fill(image, sr, sc, old, color);
    return image;
}

static void fill(int[][] image, int r, int c, int old, int color) {
    if (r < 0 || r >= image.length || c < 0 || c >= image[0].length || image[r][c] != old) return;
    image[r][c] = color;
    for (int[] d : new int[][] {{1, 0}, {-1, 0}, {0, 1}, {0, -1}})
        fill(image, r + d[0], c + d[1], old, color);
}
```

```go
func floodFill(image [][]int, sr, sc, color int) [][]int {
	old := image[sr][sc]
	if old == color { // 不判断的话会反复染同一个格子
		return image
	}
	rows, cols := len(image), len(image[0])
	var dfs func(r, c int)
	dfs = func(r, c int) {
		if r >= 0 && r < rows && c >= 0 && c < cols && image[r][c] == old {
			image[r][c] = color
			for _, d := range [][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}} {
				dfs(r+d[0], c+d[1])
			}
		}
	}
	dfs(sr, sc)
	return image
}
```

## 复杂度与常见错误

BFS 和 DFS 都让每个顶点、每条边各处理常数次，时间 O(V + E)，网格上就是 O(行数 × 列数)。

- 忘记记录访问过的点，在有环的图里会死循环。
- BFS 在出队时才标记，同一个点会被多次放进队列。
- 无向图只加了一个方向的边。

## 延伸：最小生成树

图上另一个经典问题是最小生成树：用总权重最小的一组边把所有点连通。Kruskal 算法把边从轻到重排好，依次判断：连接两个不同的连通块就选，否则会成环，跳过。判断用的是并查集，后面的并查集专题会细讲。

