chapters.bodyEn:
A graph is a set of **vertices** joined by **edges**. Social networks, maps, course prerequisites and mazes are all graphs. A tree is a special graph: connected and without cycles.

```mermaid
flowchart LR
  accTitle: An undirected graph with 5 vertices
  n0((0)) --- n1((1))
  n0 --- n2((2))
  n1 --- n3((3))
  n2 --- n3
  n3 --- n4((4))
```

Edges can have a direction (a directed graph, like "A follows B") and a weight (like the length of a road).

## Storing a graph

| Representation | What it is | Space | Good for |
|---|---|---|---|
| Adjacency list | a list of neighbours per vertex | O(V + E) | most problems, especially sparse graphs |
| Adjacency matrix | a V×V table, `m[u][v]` says whether an edge exists | O(V²) | few vertices, O(1) "are these connected?" |

Problems usually give an edge list; build the adjacency list first:

```python
from collections import defaultdict

def build(edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)    # undirected: add both directions
    return graph
```

```cpp
unordered_map<int, vector<int>> build(const vector<pair<int, int>>& edges) {
    unordered_map<int, vector<int>> graph;
    for (auto [u, v] : edges) {
        graph[u].push_back(v);
        graph[v].push_back(u);  // undirected: add both directions
    }
    return graph;
}
```

```java
import java.util.*;

static Map<Integer, List<Integer>> build(int[][] edges) {
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] e : edges) {
        graph.computeIfAbsent(e[0], key -> new ArrayList<>()).add(e[1]);
        graph.computeIfAbsent(e[1], key -> new ArrayList<>()).add(e[0]);  // undirected: add both directions
    }
    return graph;
}
```

```go
func build(edges [][2]int) map[int][]int {
	graph := map[int][]int{}
	for _, e := range edges {
		u, v := e[0], e[1]
		graph[u] = append(graph[u], v)
		graph[v] = append(graph[v], u) // undirected: add both directions
	}
	return graph
}
```

## Breadth-first search (BFS)

Start at the source, visit everything one edge away, then everything two edges away, and so on, using a queue. Because it expands ring by ring, **on an unweighted graph BFS reaches each vertex first by a path with the fewest edges**.

```python
from collections import deque

def bfs_distance(graph, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if v not in dist:          # record on enqueue so nothing is queued twice
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist
```

```cpp
unordered_map<int, int> bfsDistance(unordered_map<int, vector<int>>& graph, int start) {
    unordered_map<int, int> dist = {{start, 0}};
    queue<int> q;
    q.push(start);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : graph[u])
            if (!dist.count(v)) {  // record on enqueue so nothing is queued twice
                dist[v] = dist[u] + 1;
                q.push(v);
            }
    }
    return dist;
}
```

```java
import java.util.*;

static Map<Integer, Integer> bfsDistance(Map<Integer, List<Integer>> graph, int start) {
    Map<Integer, Integer> dist = new HashMap<>(Map.of(start, 0));
    Deque<Integer> queue = new ArrayDeque<>(List.of(start));
    while (!queue.isEmpty()) {
        int u = queue.poll();
        for (int v : graph.getOrDefault(u, List.of()))
            if (!dist.containsKey(v)) {  // record on enqueue so nothing is queued twice
                dist.put(v, dist.get(u) + 1);
                queue.offer(v);
            }
    }
    return dist;
}
```

```go
func bfsDistance(graph map[int][]int, start int) map[int]int {
	dist := map[int]int{start: 0}
	queue := []int{start}
	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		for _, v := range graph[u] {
			if _, seen := dist[v]; !seen { // record on enqueue so nothing is queued twice
				dist[v] = dist[u] + 1
				queue = append(queue, v)
			}
		}
	}
	return dist
}
```

From 0 in the graph above, the distances are 0→0, 1→1, 2→1, 3→2, 4→3.

The demo runs BFS on a grid: queued cells spread out one distance at a time, so the first time the goal is reached takes the fewest steps.

