## 归并排序：分而治之

把数组分成两半，分别排好，再把两个有序数组合并：

```python
def merge_sort(a):
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    left, right = merge_sort(a[:mid]), merge_sort(a[mid:])
    merged, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:        # 用 <= 才能保证稳定
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    return merged + left[i:] + right[j:]
```

```cpp
vector<int> mergeSort(const vector<int>& a) {
    if (a.size() <= 1) return a;
    auto mid = a.begin() + a.size() / 2;
    vector<int> left = mergeSort(vector<int>(a.begin(), mid));
    vector<int> right = mergeSort(vector<int>(mid, a.end()));
    vector<int> merged;
    size_t i = 0, j = 0;
    while (i < left.size() && j < right.size()) {
        if (left[i] <= right[j])  // 用 <= 才能保证稳定
            merged.push_back(left[i++]);
        else
            merged.push_back(right[j++]);
    }
    merged.insert(merged.end(), left.begin() + i, left.end());
    merged.insert(merged.end(), right.begin() + j, right.end());
    return merged;
}
```

```java
import java.util.*;

static int[] mergeSort(int[] a) {
    if (a.length <= 1) return a;
    int mid = a.length / 2;
    int[] left = mergeSort(Arrays.copyOfRange(a, 0, mid));
    int[] right = mergeSort(Arrays.copyOfRange(a, mid, a.length));
    int[] merged = new int[a.length];
    int i = 0, j = 0, k = 0;
    while (i < left.length && j < right.length)
        merged[k++] = left[i] <= right[j] ? left[i++] : right[j++];  // 用 <= 才能保证稳定
    while (i < left.length) merged[k++] = left[i++];
    while (j < right.length) merged[k++] = right[j++];
    return merged;
}
```

```go
func mergeSort(a []int) []int {
	if len(a) <= 1 {
		return a
	}
	mid := len(a) / 2
	left, right := mergeSort(a[:mid]), mergeSort(a[mid:])
	merged := make([]int, 0, len(a))
	i, j := 0, 0
	for i < len(left) && j < len(right) {
		if left[i] <= right[j] { // 用 <= 才能保证稳定
			merged = append(merged, left[i])
			i++
		} else {
			merged = append(merged, right[j])
			j++
		}
	}
	merged = append(merged, left[i:]...)
	return append(merged, right[j:]...)
}
```

一共 log n 层，每层合并的总工作量是 O(n)，合计 O(n log n)。

