    sort(nums.begin(), nums.end());  // sorts in place
    vector<string> words = {"bb", "a", "ccc"};
    stable_sort(words.begin(), words.end(),
                [](const string& x, const string& y) { return x.size() < y.size(); });  // by length: a bb ccc
}
```

```java
import java.util.*;

static void demo() {
    int[] nums = {3, 1, 2};
    int[] copy = nums.clone();
