## 一个不容易写错的模板

二分最常出错的是边界：`<` 还是 `<=`，`mid` 还是 `mid + 1`，什么时候会死循环。推荐记住一个固定的写法：**找第一个满足条件的位置**。

```python
def lower_bound(nums, target):
    """第一个 >= target 的下标；都比 target 小时返回 len(nums)。"""
    lo, hi = 0, len(nums)        # 答案一定在 [lo, hi] 里
    while lo < hi:               # 区间里还有不止一个候选
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1         # mid 不满足，答案在它右边
        else:
            hi = mid             # mid 满足，可能就是答案，保留它
    return lo
```

```cpp
// 第一个 >= target 的下标；都比 target 小时返回 nums.size()
int lowerBound(const vector<int>& nums, int target) {
    int lo = 0, hi = nums.size();      // 答案一定在 [lo, hi] 里
    while (lo < hi) {                  // 区间里还有不止一个候选
        int mid = lo + (hi - lo) / 2;  // 这样写，lo + hi 不会溢出
        if (nums[mid] < target)
            lo = mid + 1;              // mid 不满足，答案在它右边
        else
            hi = mid;                  // mid 满足，可能就是答案，保留它
    }
    return lo;
}
```

```java
// 第一个 >= target 的下标；都比 target 小时返回 nums.length
static int lowerBound(int[] nums, int target) {
    int lo = 0, hi = nums.length;      // 答案一定在 [lo, hi] 里
    while (lo < hi) {                  // 区间里还有不止一个候选
        int mid = lo + (hi - lo) / 2;  // 这样写，lo + hi 不会溢出
        if (nums[mid] < target)
            lo = mid + 1;              // mid 不满足，答案在它右边
        else
            hi = mid;                  // mid 满足，可能就是答案，保留它
    }
    return lo;
}
```

```go
// 第一个 >= target 的下标；都比 target 小时返回 len(nums)
func lowerBound(nums []int, target int) int {
	lo, hi := 0, len(nums) // 答案一定在 [lo, hi] 里
	for lo < hi {          // 区间里还有不止一个候选
		mid := lo + (hi-lo)/2
		if nums[mid] < target {
			lo = mid + 1 // mid 不满足，答案在它右边
		} else {
			hi = mid // mid 满足，可能就是答案，保留它
		}
	}
	return lo
}
```

为什么不会死循环：`lo < hi` 时，`mid` 总是严格小于 `hi`，所以两个分支都会让区间变小。

