        list.remove(Integer.valueOf(4));
        list.sort(null);
        System.out.println(list);

        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        for (int[] row : new int[][] {{5, 50}, {1, 10}}) pq.offer(row);
        Deque<Integer> st = new ArrayDeque<>();
        st.push(1);
        st.push(2);
        System.out.println(pq.poll()[1] + " " + st.peek());

        Map<String, List<Integer>> groups = new HashMap<>();
        groups.computeIfAbsent("odd", z -> new ArrayList<>()).add(3);
        groups.computeIfAbsent("odd", z -> new ArrayList<>()).add(5);
        Set<Integer> seen = new HashSet<>();
        int dup = -1;
        for (int x : new int[] {5, 8, 5}) if (!seen.add(x)) dup = x;
        System.out.println(groups.get("odd") + " " + dup);

        TreeSet<Integer> ts = new TreeSet<>(List.of(10, 20, 30));
        TreeMap<Integer, String> tm = new TreeMap<>(Map.of(1, "a", 5, "b", 9, "c"));
        System.out.println(ts.floor(25) + " " + ts.ceiling(31) + " " + tm.headMap(5) + " " + tm.lastKey());
